import React, { useState, useMemo } from 'react';
import SubjectTable from './SubjectTable';
import SubjectModal from './SubjectModal';
import Pagination from './Pagination';

// Initial data updated to match the UI screenshot, including workload columns
const initialSubjects = [
  { id: 'EXPL001', code: 'EXPL001', name: 'Example 1', term: 'Spring', coordinator: 'Tom', version: 1, date: '2024-11-18', delivery: 'Lecture based', totalWorkload: '51.5%', allocatedWorkload: '51.5%', unallocatedWorkload: '0' },
  { id: 'EXPL002', code: 'EXPL002', name: 'Example 2', term: 'Autumn', coordinator: 'Usha', version: 1, date: '2024-08-25', delivery: 'Project based', totalWorkload: '51.5%', allocatedWorkload: '51.5%', unallocatedWorkload: '0' },
  { id: 'EXPL003', code: 'EXPL003', name: 'Example 3', term: '1H', coordinator: 'Victoria', version: 1, date: '2024-04-08', delivery: 'Lecture based', totalWorkload: '51.5%', allocatedWorkload: '51.5%', unallocatedWorkload: '0' },
  { id: 'EXPL004', code: 'EXPL004', name: 'Example 4', term: '2H', coordinator: 'Fred', version: 1, date: '2024-07-21', delivery: 'Project based', totalWorkload: '51.5%', allocatedWorkload: '51.5%', unallocatedWorkload: '0' },
  { id: 'EXPL005', code: 'EXPL005', name: 'Example 5', term: 'Q1', coordinator: 'Ian', version: 1, date: '2024-03-05', delivery: 'Lecture based', totalWorkload: '51.5%', allocatedWorkload: '51.5%', unallocatedWorkload: '0' },
  { id: 'EXPL006', code: 'EXPL006', name: 'Example 6', term: 'Q2', coordinator: 'Jane', version: 1, date: '2024-11-18', delivery: 'Lecture based', totalWorkload: '51.5%', allocatedWorkload: '51.5%', unallocatedWorkload: '0' },
];

function SubjectManagementPage() {
  const [subjects, setSubjects] = useState(initialSubjects);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSubject, setEditingSubject] = useState(null);

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(10);

  const handleAddSubjectClick = () => {
    setEditingSubject(null);
    setIsModalOpen(true);
  };

  const handleEditSubject = (subject) => {
    setEditingSubject(subject);
    setIsModalOpen(true);
  };

  const handleDeleteSubject = (subjectId) => {
    if (window.confirm('Are you sure you want to delete this subject?')) {
        setSubjects(subjects.filter(s => s.id !== subjectId));
    }
  };

  const handleSaveSubject = (subjectData) => {
    if (editingSubject) {
      // Update existing subject
      setSubjects(subjects.map(s => s.id === editingSubject.id ? { ...s, ...subjectData } : s));
    } else {
      // Add new subject with placeholder workload data
      const newSubject = { 
        ...subjectData, 
        id: `EXPL${Date.now()}`,
        totalWorkload: '0%', 
        allocatedWorkload: '0%', 
        unallocatedWorkload: '0' 
    };
      setSubjects([newSubject, ...subjects]);
    }
    setIsModalOpen(false);
  };

  // Memoized pagination calculation
  const paginatedSubjects = useMemo(() => {
    const startIndex = (currentPage - 1) * rowsPerPage;
    const endIndex = startIndex + rowsPerPage;
    return subjects.slice(startIndex, endIndex);
  }, [subjects, currentPage, rowsPerPage]);

  return (
    <div className="subject-management-container">
      <header className="page-header">
        <button onClick={handleAddSubjectClick} className="add-subject-btn">Add Subject</button>
      </header>

      <SubjectTable 
        subjects={paginatedSubjects}
        onEdit={handleEditSubject}
        onDelete={handleDeleteSubject}
      />

      <Pagination
        totalRows={subjects.length}
        rowsPerPage={rowsPerPage}
        currentPage={currentPage}
        onPageChange={setCurrentPage}
        onRowsPerPageChange={setRowsPerPage}
      />

      {isModalOpen && (
        <SubjectModal 
          subject={editingSubject}
          onClose={() => setIsModalOpen(false)}
          onSave={handleSaveSubject}
        />
      )}
    </div>
  );
}

export default SubjectManagementPage;
